D='def-diagonal-torus-characters-and-weyl-action';W='thm-weyl-stabilizer-controls-principal-series-endomorphisms';B='def-standard-intertwining-operators-for-finite-principal-series';C='lem-principal-series-endomorphisms-as-the-chi-idempotent-corner';LB='lem-standard-intertwiners-form-a-basis-of-the-principal-series-endomorphism-algebra';LP='lem-length-additive-products-of-standard-intertwiners';RP='lem-rank-one-hecke-parameter-for-equal-torus-characters';G='thm-general-finite-principal-series-endomorphism-algebra';T='thm-tits-deformation-for-the-type-a-hecke-algebra';F='lem-formal-triviality-of-one-parameter-semisimple-algebras'
